using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class UnitReplyRecoveryTests
{
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    static NewMilitaryInput Input(WorldSession s,NewMilitaryAction a)=>new(new("request:unit-reply/"+s.Revision+"/"+a),a);
    static void Send(WorldSession s,NewMilitaryAction a,long amount=0){var r=s.DecideNewMilitary(Input(s,a) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
    static WorldSession Ready(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Send(s,NewMilitaryAction.Request);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+30000,a.Y),B=new(a.X+30000,a.Y+16000)},s.PlayerControl,s.Revision).Code);At(s,ArmyEnd(s)+1);return s;}
    static long ArmyEnd(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.Max(r=>r.LastOrDefault()?.EndAt??s.Seconds);
    static WorldSession Failed(bool known=true){var s=Ready();Send(s,NewMilitaryAction.Recall);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);Send(s,NewMilitaryAction.RemoteRecall);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Single();At(s,d.DueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().Delivered);if(known)At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().ReplyDueAt);return s;}
    static WorldSession HomeReady(){var s=Ready();Send(s,NewMilitaryAction.Recall);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,Math.Max(ArmyEnd(s),j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);return s;}
    static TroopDispatch Query(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();
    static TroopReceipt Answer(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Receipts.Last();
    static UnitPostInquiryAnswer Quote(ContractWorld w){var r=w.NewMilitary!.UnitInquiry!.Receipts.Last();return ContractJson.Read<UnitPostInquiryAnswer>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==r.ReplyMessage).Body));}
    static void Ask(WorldSession s,NewMilitaryAction action=NewMilitaryAction.InquireUnitKnown,bool policy=true){var r=s.DecideNewMilitary(Input(s,action) with{PostPolicy=policy?NewGameMilitary.UnitReplyRecoveryContract:null},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static void MoveAway(WorldSession s){var home=NewGameMilitary.Home(s.DiagnosticSnapshot(),0);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(home.X+5000,home.Y)},s.PlayerControl,s.Revision).Code);}
    static WorldSession FailedReply(bool policy=true){var s=Ready();Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);Ask(s,policy:policy);At(s,Query(s).DueAt);MoveAway(s);At(s,Answer(s).ReplyDueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Replies.Last().Received);return s;}
    [Fact]public void ReportMustPhysicallyReturnBeforeAutomaticRetry(){var s=FailedReply();var w=s.DiagnosticSnapshot();var r=Answer(s);var d=Query(s);var f=Assert.Single(w.NewMilitary!.ReplyRecovery!.Flights);Assert.Equal(UnitReplyLeg.FailureReport,f.Kind);Assert.Equal(r.ReplyDestination,f.Origin);Assert.Equal(d.Destination,f.Destination);Assert.True(f.Route.Length>0);Assert.False(MessageFlow.FailureKnown(w.Messaging,r.ReplyAttempt,d.Recipient.Value));Assert.Single(w.Messaging.Attempts,a=>a.MessageId==r.ReplyMessage);At(s,f.DueAt-1);Assert.Single(s.DiagnosticSnapshot().Messaging.Attempts,a=>a.MessageId==r.ReplyMessage);At(s,f.DueAt);w=s.DiagnosticSnapshot();Assert.True(MessageFlow.FailureKnown(w.Messaging,r.ReplyAttempt,d.Recipient.Value));Assert.Equal(2,w.Messaging.Attempts.Count(a=>a.MessageId==r.ReplyMessage));}
    [Fact]public void SameOriginalReplyArrivesWithoutRewritingFirstLoss(){var s=FailedReply();var r=Answer(s);var w=s.DiagnosticSnapshot();string body=w.Messaging.Messages.Single(m=>m.Id==r.ReplyMessage).Body;var failed=w.NewMilitary!.UnitInquiry!.Replies.Last();var definition=ContractJson.CanonicalHash(w.Definitions);Send(s,NewMilitaryAction.PersonalHome);var report=w.NewMilitary.ReplyRecovery!.Flights.Single();At(s,report.DueAt);var retry=s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Last();Assert.Equal(UnitReplyLeg.Retry,retry.Kind);At(s,retry.DueAt);w=s.DiagnosticSnapshot();Assert.Equal(body,w.Messaging.Messages.Single(m=>m.Id==r.ReplyMessage).Body);Assert.Equal(failed,w.NewMilitary!.UnitInquiry!.Replies.Last());Assert.Single(w.Messaging.Receipts,x=>x.MessageId==r.ReplyMessage);Assert.True(MessageFlow.Knows(w.Messaging,r.ReplyMessage,w.PlayerControl.Value));Assert.Contains("40人",NewGameMilitary.UnitInquiryStatus(w));Assert.Equal(definition,ContractJson.CanonicalHash(w.Definitions));}
    [Fact]public void OlderUnflaggedReplyNeverGetsAutomaticPolicy(){var s=FailedReply(false);Assert.Null(s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery);At(s,s.Seconds+100);Assert.Null(s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery);Assert.Single(s.DiagnosticSnapshot().Messaging.Attempts,a=>a.MessageId==Answer(s).ReplyMessage);}
    [Fact]public void ThreeAttemptsStopAfterFinalPhysicalFailureReport(){var s=HomeReady();Ask(s,NewMilitaryAction.InquireUnitHome);MoveAway(s);At(s,Query(s).DueAt);At(s,Answer(s).ReplyDueAt);for(int n=0;n<8;n++){var w=s.DiagnosticSnapshot();var next=w.NewMilitary!.ReplyRecovery!.Flights.Where(f=>f.DueAt>s.Seconds).MinBy(f=>f.DueAt);if(next==null)break;At(s,next.DueAt);}var end=s.DiagnosticSnapshot();Assert.Equal(3,end.Messaging.Attempts.Count(a=>a.MessageId==Answer(s).ReplyMessage));Assert.Equal(3,end.NewMilitary!.ReplyRecovery!.Flights.Count(f=>f.Kind==UnitReplyLeg.FailureReport));Assert.Equal(2,end.NewMilitary.ReplyRecovery.Flights.Count(f=>f.Kind==UnitReplyLeg.Retry));Assert.DoesNotContain(end.Messaging.Receipts,r=>r.MessageId==Answer(s).ReplyMessage);int count=end.NewMilitary.ReplyRecovery.Flights.Length;At(s,s.Seconds+50);Assert.Equal(count,s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Length);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ReportAndRetryRestoreSameFuture(int step){var s=FailedReply();Send(s,NewMilitaryAction.PersonalHome);var report=s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Single();if(step>0)At(s,report.DueAt-1);if(step>1)At(s,report.DueAt);if(step>2)At(s,s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Last().DueAt);var copy=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));long until=Math.Max(s.Seconds+3,report.DueAt+40);foreach(var x in new[]{s,copy})At(x,until);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(copy.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]public void ForgedRecoveryHistoryIsRejected(int kind){var s=FailedReply();if(kind==4)At(s,s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Single().DueAt);var w=s.DiagnosticSnapshot();var x=w.NewMilitary!.ReplyRecovery!;if(kind==0)x.Flights[0]=x.Flights[0] with{Origin=new(0,0)};if(kind==1)w.NewMilitary=w.NewMilitary with{ReplyRecovery=x with{Flights=[]}};if(kind==2)w.NewMilitary=w.NewMilitary with{ReplyRecovery=x with{Flights=[..x.Flights,x.Flights[0]]}};if(kind==3){string id=x.Flights[0].Message;w.Messaging.Messages=w.Messaging.Messages.Select(m=>m.Id==id?m with{SenderId=NewGameMilitary.UnitIds[0].Value}:m).ToArray();}if(kind==4)x.Arrivals[0]=x.Arrivals[0] with{Delivered=false};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void WrongPolicyIsRejectedWithoutMutation(){var s=HomeReady();string hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());var result=s.DecideNewMilitary(Input(s,NewMilitaryAction.InquireUnitHome) with{PostPolicy="unknown"},s.PlayerControl,s.Revision);Assert.Equal(ResultCode.NotAvailable,result.Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact]public void OldEnvelopeAndSaveOmitOptionalPolicy(){var s=HomeReady();Ask(s,NewMilitaryAction.InquireUnitHome,false);string json=System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.DiagnosticSnapshot().NewMilitary));Assert.DoesNotContain("ReplyRecovery",json);Assert.DoesNotContain("PostPolicy",json);string body=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==Query(s).Message).Body;Assert.DoesNotContain("ReplyPolicy",body);Assert.Null(ContractJson.Read<UnitPostInquiry>(System.Text.Encoding.UTF8.GetBytes(body)).ReplyPolicy);}
    [Fact]public void PolicyInputIsIdempotentAndCannotChangeAfterAcceptance(){var s=HomeReady();var i=Input(s,NewMilitaryAction.InquireUnitHome) with{PostPolicy=NewGameMilitary.UnitReplyRecoveryContract};Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(i,s.PlayerControl,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.DecideNewMilitary(i with{PostPolicy=null},s.PlayerControl,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches);}
    [Fact]public void MovedUnitDoesNotReceiveFailureAtOldSendingPoint(){var s=HomeReady();Send(s,NewMilitaryAction.Attach);Send(s,NewMilitaryAction.CombatPermit);At(s,s.Seconds+2);Open(s);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+5000,a.Y),B=new(a.X+5000,a.Y+10000)},s.PlayerControl,s.Revision).Code);At(s,ArmyEnd(s)+1);long start=s.Seconds;Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.CombatStart) with{MotionContract=NewGameMilitary.RoutContract},s.PlayerControl,s.Revision).Code);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);var w=s.DiagnosticSnapshot();var known=w.NewMilitary!.Withdrawal!.Sightings.Last().Position;var path=RegionalGround.Plan(NewGameMilitary.PersonPosition(w,s.Seconds),known,s.Seconds,courier:true,atlas:true);long delay=Math.Max(1,(path.LastOrDefault()?.EndAt??s.Seconds)-s.Seconds);long send=start+9-delay;Assert.True(send>=s.Seconds,"fixture must reach home before the last pre-rout inquiry window");At(s,send);Ask(s);At(s,Query(s).DueAt);Assert.True(Answer(s).Delivered);MoveAway(s);At(s,Answer(s).ReplyDueAt);var report=Assert.Single(s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights);At(s,report.DueAt);w=s.DiagnosticSnapshot();Assert.NotEqual(report.Destination,NewGameMilitary.Position(w,0,s.Seconds));Assert.False(w.NewMilitary!.ReplyRecovery!.Arrivals.Single().Delivered);Assert.Equal(2,w.NewMilitary.ReplyRecovery.Holdings.Length);Assert.Single(NewGameMilitary.CourierFrames(w,s.Seconds),f=>f.Holding);Assert.False(MessageFlow.FailureKnown(w.Messaging,Answer(s).ReplyAttempt,NewGameMilitary.UnitIds[0].Value));Assert.Single(w.Messaging.Attempts,t=>t.MessageId==Answer(s).ReplyMessage);}
    [Fact]public void PolicyCannotBeHiddenOnUnrelatedLordInquiry(){var s=HomeReady();string before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(Input(s,NewMilitaryAction.Inquire) with{PostPolicy=NewGameMilitary.UnitReplyRecoveryContract},s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));Send(s,NewMilitaryAction.Inquire);}
    [Fact]public void HoldingAndFreshRetryCarrierHaveDistinctPhysicalPlaces(){var s=FailedReply();Send(s,NewMilitaryAction.PersonalHome);At(s,s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Single().DueAt);At(s,s.Seconds+1);var w=s.DiagnosticSnapshot();var holding=Assert.Single(w.NewMilitary!.ReplyRecovery!.Holdings);var frames=NewGameMilitary.CourierFrames(w,s.Seconds);var keeper=Assert.Single(frames,f=>f.Holding);var rider=Assert.Single(frames,f=>!f.Holding);Assert.Equal(holding.Holder,keeper.Carrier);Assert.NotEqual(keeper.Carrier,rider.Carrier);Assert.Equal(holding.Position,keeper.Position);Assert.NotEqual(keeper.Position,rider.Position);}
    [Fact]public void ForgedHoldingPositionIsRejected(){var s=FailedReply();At(s,s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Single().DueAt);var w=s.DiagnosticSnapshot();w.NewMilitary!.ReplyRecovery!.Holdings[0]=w.NewMilitary.ReplyRecovery.Holdings[0] with{Position=new(0,0)};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void MissingRecoveryArrivalIsRejectedCleanly(){var s=FailedReply();At(s,s.DiagnosticSnapshot().NewMilitary!.ReplyRecovery!.Flights.Single().DueAt);var w=s.DiagnosticSnapshot();w.NewMilitary=w.NewMilitary! with{ReplyRecovery=w.NewMilitary!.ReplyRecovery! with{Arrivals=[]}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
}
